80	int MixedStreamerReducer::init(const ailego::Params &params) {
81	  enable_pk_rewrite_ =
82	      params.get_as_bool(PARAM_MIXED_STREAMER_REDUCER_ENABLE_PK_REWRITE);
83	  params.get(PARAM_MIXED_STREAMER_REDUCER_NUM_OF_ADD_THREADS,
84	             &num_of_add_threads_);
85	  if (num_of_add_threads_ <= 0) {
86	    LOG_ERROR("Wrong parameter. %s must be set greater than 0.",
87	              PARAM_MIXED_STREAMER_REDUCER_NUM_OF_ADD_THREADS.c_str());
88	    return IndexError_InvalidArgument;
89	  }
90	
91	  params_ = params;
92	
93	  state_ = STATE_INITED;
94	  return 0;
95	}
