97	int MixedStreamerReducer::cleanup() {
98	  streamers_.clear();
99	  source_streamers_reformers_.clear();
100	  merged_holder_.reset();
101	  if (target_streamer_) {
102	    target_streamer_->cleanup();
103	  }
104	
105	  if (target_builder_) {
106	    target_builder_->cleanup();
107	  }
108	
109	  stats_.clear_attributes();
110	  state_ = STATE_UNINITED;
111	  return 0;
112	}
