114	int MixedStreamerReducer::set_target_streamer_wiht_info(
115	    const IndexBuilder::Pointer builder, const IndexStreamer::Pointer streamer,
116	    const IndexConverter::Pointer converter,
117	    const IndexReformer::Pointer reformer,
118	    const IndexQueryMeta &original_query_meta,
119	    const std::shared_ptr<zvec::turbo::Quantizer> &quantizer) {
120	  if (state_ != STATE_INITED) {
121	    LOG_ERROR("Set target streamer after init");
122	    return IndexError_Uninitialized;
123	  }
124	
125	  target_builder_ = builder;
126	  target_streamer_ = streamer;
127	  target_builder_converter_ = converter;
128	  target_streamer_reformer_ = reformer;
129	  target_streamer_quantizer_ = quantizer;
130	  original_query_meta_ = original_query_meta;
131	
132	  is_sparse_ =
133	      target_streamer_->meta().meta_type() == IndexMeta::MetaType::MT_SPARSE;
134	
135	  state_ = STATE_STREAMER_SET;
136	  return 0;
137	}
