317	int MixedStreamerReducer::dump(const IndexDumper::Pointer &dumper) {
318	  LOG_INFO("Begin brute force reducer dump");
319	
320	  if (state_ != STATE_REDUCE) {
321	    LOG_WARN("Reduce first before dump");
322	    return IndexError_NoReady;
323	  }
324	
325	  ailego::ElapsedTime timer;
326	  int ret = 0;
327	  if (target_builder_ != nullptr) {
328	    ret = target_builder_->dump(dumper);
329	  } else {
330	    ret = target_streamer_->dump(dumper);
331	  }
332	  if (ret == 0 && merged_holder_ && merged_holder_->status() != 0) {
333	    ret = merged_holder_->status();
334	  }
335	  if (ret == IndexError_NotImplemented) {
336	    LOG_WARN("Dump index not implemented");
337	  } else if (ret < 0) {
338	    LOG_ERROR("Failed to dump in streamer");
339	  }
340	
341	  return ret;
342	}
