477	void MixedStreamerReducer::add_vec(int *result) {
478	  ailego::ElapsedTime timer;
479	  auto target_streamer_context = target_streamer_->create_context();
480	  auto target_streamer_query_meta = IndexQueryMeta{
481	      IndexMeta::MetaType::MT_DENSE, target_streamer_->meta().data_type(),
482	      target_streamer_->meta().dimension()};
483	  // Quantizer-encoded layouts append an extra meta tail per record
484	  // (e.g. turbo Int8Quantizer); without it the element size would not match
485	  // the streamer meta and every add would be rejected.
486	  target_streamer_query_meta.set_extra_meta_size(
487	      target_streamer_->meta().extra_meta_size());
488	
489	  AILEGO_DEFER([&]() {
490	    // make producer quit
491	    mt_list_.done();
492	  });
493	
494	  VectorItem vector_item;
495	  while (mt_list_.consume(&vector_item)) {
496	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
497	      LOG_DEBUG("add_vec cancelled.");
498	      return;
499	    }
500	
501	    const void *vector = vector_item.vec_.data();
502	    std::string new_vector;
503	    IndexQueryMeta add_meta = target_streamer_query_meta;
504	
505	    if (vector_item.needs_convert_) {
506	      // Bytes are still in the original input format; re-encode them into
507	      // the target layout. A target without quantizer or reformer stores
508	      // the original format directly, so no encoding is needed.
509	      if (target_streamer_quantizer_ != nullptr) {
510	        IndexQueryMeta quantized_meta;
511	        if (target_streamer_quantizer_->quantize(vector, original_query_meta_,
512	                                                 &new_vector,
513	                                                 &quantized_meta) != 0) {
514	          LOG_ERROR("Failed to quantize vector. pkey[%zu]",
515	                    (size_t)vector_item.pkey_);
516	          *result = IndexError_Runtime;
517	          return;
518	        }
519	        vector = new_vector.data();
520	        add_meta = quantized_meta;
521	      } else if (target_streamer_reformer_ != nullptr) {
522	        IndexQueryMeta new_meta;
523	        if (target_streamer_reformer_->convert(vector, original_query_meta_,
524	                                               &new_vector, &new_meta) != 0) {
525	          LOG_ERROR("Failed to transform vector");
526	          *result = IndexError_Runtime;
527	          return;
528	        }
529	        vector = new_vector.data();
530	      }
531	    }
532	
533	    // TODO: use id instead of key
534	    int ret = target_streamer_->add_with_id_impl(
535	        (uint32_t)vector_item.pkey_, vector, add_meta, target_streamer_context);
536	    if (ret != 0) {
537	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
538	                ret, IndexError::What(ret), (size_t)vector_item.pkey_);
539	      *result = ret;
540	      return;
541	    }
542	  }
543	
544	  *result = 0;
545	  LOG_DEBUG("add_vec. cost time: [%zu]s", (size_t)timer.seconds());
546	  return;
547	}
