549	void MixedStreamerReducer::add_sparse_vec(int *result) {
550	  ailego::ElapsedTime timer;
551	  auto target_streamer_context = target_streamer_->create_context();
552	  auto target_streamer_query_meta = IndexQueryMeta{
553	      IndexMeta::MetaType::MT_SPARSE,
554	      target_streamer_->meta().data_type(),
555	  };
556	
557	  auto need_convert = !is_target_and_source_same_reformer_ &&
558	                      target_streamer_reformer_ != nullptr;
559	
560	  AILEGO_DEFER([&]() {
561	    // make producer quit
562	    sparse_mt_list_.done();
563	  });
564	
565	  SparseVectorItem sparse_vector_item;
566	  while (sparse_mt_list_.consume(&sparse_vector_item)) {
567	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
568	      LOG_DEBUG("add_sparse_vec cancelled.");
569	      return;
570	    }
571	    auto sparse_count = sparse_vector_item.sparse_indices_.size();
572	    auto indices = sparse_vector_item.sparse_indices_.data();
573	    auto values = sparse_vector_item.sparse_values_.data();
574	
575	    std::string converted_sparse_values_buffer;
576	    if (need_convert) {
577	      IndexQueryMeta new_meta;
578	      if (target_streamer_reformer_->convert(
579	              sparse_count, indices, values, original_query_meta_,
580	              &converted_sparse_values_buffer, &new_meta) != 0) {
581	        LOG_ERROR("Failed to transform vector");
582	        *result = IndexError_Runtime;
583	        return;
584	      }
585	      values = converted_sparse_values_buffer.data();
586	      target_streamer_query_meta = new_meta;
587	    }
588	
589	    // TODO: use id instead of key
590	    int ret = target_streamer_->add_with_id_impl(
591	        (uint32_t)sparse_vector_item.pkey_, sparse_count, indices, values,
592	        target_streamer_query_meta, target_streamer_context);
593	    if (ret != 0) {
594	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
595	                ret, IndexError::What(ret), (size_t)sparse_vector_item.pkey_);
596	      *result = ret;
597	      return;
598	    }
599	  }
600	
601	  *result = 0;
602	  LOG_DEBUG("add_sparse_vec. cost time: [%zu]s", (size_t)timer.seconds());
603	  return;
604	}
605	
606	
607	int MixedStreamerReducer::read_sparse_vec(size_t source_streamer_index,
608	                                          const IndexFilter &filter,
609	                                          const uint32_t id_offset,
610	                                          uint32_t *next_id) {
611	  const auto &streamer = streamers_[source_streamer_index];
612	  const auto &reformer = source_streamers_reformers_[source_streamer_index];
613	  const bool need_revert =
614	      !is_target_and_source_same_reformer_ && reformer != nullptr;
615	
616	  IndexStreamer::SparseProvider::Pointer provider =
617	      streamer->create_sparse_provider();
618	  IndexStreamer::SparseProvider::Iterator::Pointer iterator =
619	      provider->create_iterator();
620	
621	  while (iterator->is_valid()) {
622	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
623	      LOG_DEBUG("read_sparse_vec cancelled.");
624	      return 0;
625	    }
626	    if (filter(iterator->key() + (uint64_t)id_offset)) {
627	      (*stats_.mutable_filtered_count())++;
628	      iterator->next();
629	      continue;
630	    }
631	
632	    auto sparse_count = iterator->sparse_count();
633	    std::vector<uint32_t> sparse_indices(sparse_count);
634	    std::string sparse_values;
635	
636	    if (need_revert) {
637	      std::string new_sparse_values;
638	      if (reformer->revert(iterator->sparse_count(), iterator->sparse_indices(),
639	                           iterator->sparse_data(),
640	                           {
641	                               IndexMeta::MetaType::MT_SPARSE,
642	                               streamer->meta().data_type(),
643	                           },
644	                           &new_sparse_values) != 0) {
645	        LOG_ERROR("Failed to revert the sparse vector");
646	        return IndexError_Runtime;
647	      }
648	      sparse_values = std::move(new_sparse_values);
649	    } else {
650	      sparse_values.resize(sparse_count * streamer->meta().unit_size());
651	      memcpy(sparse_values.data(), iterator->sparse_data(),
652	             sparse_values.size());
653	    }
654	
655	    // TODO: eliminate the copy
656	    memcpy(sparse_indices.data(), iterator->sparse_indices(),
657	           sparse_indices.size() * sizeof(uint32_t));
658	
659	    // TODO: use id instead of key
660	    if (!sparse_mt_list_.produce(SparseVectorItem((*next_id)++,
661	                                                  std::move(sparse_indices),
662	                                                  std::move(sparse_values)))) {
663	      LOG_ERROR("Produce vector to queue failed. key[%lu]",
664	                (size_t)iterator->key());
665	      return IndexError_Runtime;
666	    }
667	    iterator->next();
668	  }
669	  return 0;
670	}
671	
672	int MixedStreamerReducer::reduce_with_builder(const IndexFilter &filter) {
673	  std::vector<MergedProviderIndexHolder::Source> sources;
674	  sources.reserve(streamers_.size());
675	
676	  for (size_t i = 0; i < streamers_.size(); ++i) {
677	    MergedProviderIndexHolder::Source source;
678	    source.owner = streamers_[i];
679	    source.reformer = source_streamers_reformers_[i];
680	    source.quantizer = source_streamers_quantizers_[i];
681	    const auto &meta = streamers_[i]->meta();
682	    source.provider_meta = IndexQueryMeta{
683	        meta.meta_type(),
684	        meta.data_type(),
685	        meta.unit_size(),
686	        meta.dimension(),
687	        source.quantizer ? static_cast<uint32_t>(source.quantizer->type()) : 0,
688	        meta.extra_meta_size()};
689	    // Builders consume original vectors, not encoded records. Plain FP32
690	    // quantization is an identity transform; keep its zero-copy ordinal path.
691	    // Cosine normalization and FP16/INT8/INT4 storage must be decoded first.
692	    source.need_revert =
693	        source.quantizer
694	            ? source.quantizer->type() != turbo::QuantizeType::kFp32 ||
695	                  meta.extra_meta_size() != 0
696	            : source.reformer != nullptr;
697	    sources.emplace_back(std::move(source));
698	  }
699	
700	  auto holder = std::make_shared<MergedProviderIndexHolder>(
701	      original_query_meta_, std::move(sources));
702	  int ret = holder->init(filter, stop_flag_);
703	  if (ret != 0) {
704	    LOG_ERROR("Failed to initialize merged provider holder, ret=%d", ret);
705	    return ret;
706	  }
707	
708	  stats_.set_filtered_count(holder->filtered_count());
709	  merged_holder_ = holder;
710	
711	  AILEGO_DEFER([&]() { holder->set_stop_flag(nullptr); });
712	  IndexHolder::Pointer target_holder = holder;
713	  // IVF and DiskAnn propagate source read failures during dump.
714	  // Other builders retain an owned multipass snapshot, as before, so their
715	  // dump paths never depend on a source provider or its deferred error state.
716	  if (target_builder_->name() != "IVFBuilder" &&
717	      target_builder_->name() != "DiskAnnBuilder") {
718	    switch (holder->data_type()) {
719	      case IndexMeta::DataType::DT_FP32:
720	        ret = MaterializeMergedInput<IndexMeta::DataType::DT_FP32, float>(
721	            holder, &target_holder);
722	        break;
723	      case IndexMeta::DataType::DT_FP16:
724	        ret = MaterializeMergedInput<IndexMeta::DataType::DT_FP16,
725	                                     ailego::Float16>(holder, &target_holder);
726	        break;
727	      case IndexMeta::DataType::DT_INT8:
728	        ret = MaterializeMergedInput<IndexMeta::DataType::DT_INT8, int8_t>(
729	            holder, &target_holder);
730	        break;
731	      default:
732	        ret = IndexError_Unsupported;
733	        break;
734	    }
735	    if (ret != 0) {
736	      return ret;
737	    }
738	  }
739	  return this->index_build(std::move(target_holder));
740	}
741	
742	int MixedStreamerReducer::index_build(IndexHolder::Pointer target_holder) {
743	  auto threads =
744	      std::make_shared<BorrowedSingleQueueIndexThreads>(*thread_pool_);
745	  if (target_builder_converter_) {
746	    int ret = core::IndexConverter::TrainAndTransform(target_builder_converter_,
747	                                                      target_holder, threads);
748	    if (ret != 0) {
749	      LOG_ERROR("Failed to convert target holder, ret=%d", ret);
750	      return merged_holder_ && merged_holder_->status() != 0
751	                 ? merged_holder_->status()
752	                 : ret;
753	    }
754	    target_holder = target_builder_converter_->result();
755	    if (!target_holder) {
756	      LOG_ERROR("Target builder converter returned a null holder");
757	      return core::IndexError_Runtime;
758	    }
759	  }
760	  int ret = target_builder_->train(threads, target_holder);
761	  if (merged_holder_ && merged_holder_->status() != 0) {
762	    return merged_holder_->status();
763	  }
764	  if (ret != 0) {
765	    LOG_ERROR("Failed to train target builder, ret=%d", ret);
766	    return ret;
767	  }
768	  ret = target_builder_->build(std::move(threads), target_holder);
769	  if (merged_holder_ && merged_holder_->status() != 0) {
770	    return merged_holder_->status();
771	  }
772	  if (ret != 0) {
773	    LOG_ERROR("Failed to build target index, ret=%d", ret);
774	    return ret;
775	  }
776	  return 0;
777	}
