114	int MixedStreamerReducer::set_target_streamer_wiht_info(
115	    const IndexBuilder::Pointer builder, const IndexStreamer::Pointer streamer,
116	    const IndexConverter::Pointer converter,
117	    const IndexReformer::Pointer reformer,
118	    const IndexQueryMeta &original_query_meta,
119	    const std::shared_ptr<zvec::turbo::Quantizer> &quantizer) {
120	  if (state_ != STATE_INITED) {
121	    LOG_ERROR("Set target streamer after init");
122	    return IndexError_Uninitialized;
123	  }
124	
125	  target_builder_ = builder;
126	  target_streamer_ = streamer;
127	  target_builder_converter_ = converter;
128	  target_streamer_reformer_ = reformer;
129	  target_streamer_quantizer_ = quantizer;
130	  original_query_meta_ = original_query_meta;
131	
132	  is_sparse_ =
133	      target_streamer_->meta().meta_type() == IndexMeta::MetaType::MT_SPARSE;
134	
135	  state_ = STATE_STREAMER_SET;
136	  return 0;
137	}
138	
139	int MixedStreamerReducer::feed_streamer_with_reformer(
140	    IndexStreamer::Pointer streamer, const IndexReformer::Pointer reformer,
141	    const std::shared_ptr<zvec::turbo::Quantizer> &quantizer) {
142	  if (!(state_ == STATE_STREAMER_SET || state_ == STATE_FEED)) {
143	    LOG_ERROR("Set target streamer or feed before feed");
144	    return IndexError_Uninitialized;
145	  }
146	
147	  if (!streamer) {
148	    LOG_ERROR("Streamer nullptr");
149	    return IndexError_InvalidArgument;
150	  }
151	
152	  auto check_datatype = [&](const IndexMeta & /*target_meta*/,
153	                            const IndexMeta &source_meta) -> bool {
154	    if (target_builder_ && !is_sparse_) {
155	      // Builders consume decoded vectors. Legacy and Turbo postings can
156	      // describe different stored types for the same original input type.
157	      // Validate each decoded record against original_query_meta_ in read_vec.
158	      return true;
159	    }
160	    if (!streamers_.empty()) {
161	      auto &last_meta = streamers_.back()->meta();
162	      // Quantizer-encoded sources are dequantized to the original format
163	      // before the target re-encodes them, so their stored layout may
164	      // legitimately differ from another source's.
165	      if (!last_meta.quantizer_name().empty() ||
166	          !source_meta.quantizer_name().empty()) {
167	        return true;
168	      }
169	      return last_meta.data_type() == source_meta.data_type() &&
170	             last_meta.dimension() == source_meta.dimension() &&
171	             last_meta.unit_size() == source_meta.unit_size();
172	    }
173	    // TODO: check target meta
174	    return true;
175	  };
176	
177	  auto check_other = [&](const IndexMeta &target_meta,
178	                         const IndexMeta &source_meta) -> bool {
179	    return target_meta.meta_type() == source_meta.meta_type();
180	    // when create a new index, there is a case that ip_flat merged into l2_hnsw
181	    // target_meta.metric_name() == source_meta.metric_name();
182	  };
183	
184	  if (!(check_datatype(target_streamer_->meta(), streamer->meta()) &&
185	        check_other(target_streamer_->meta(), streamer->meta()))) {
186	    LOG_ERROR("Streamer meta mismatch");
187	    return IndexError_InvalidArgument;
188	  }
189	
190	  if (streamers_.empty()) {
191	    is_target_and_source_same_reformer_ =
192	        target_streamer_->meta().reformer_name() ==
193	            streamer->meta().reformer_name() &&
194	        target_streamer_->meta().quantizer_name() ==
195	            streamer->meta().quantizer_name();
196	  }
197	
198	  streamers_.push_back(streamer);
199	  source_streamers_reformers_.push_back(reformer);
200	  source_streamers_quantizers_.push_back(quantizer);
201	
202	  state_ = STATE_FEED;
203	  return 0;
204	}
205	
206	int MixedStreamerReducer::reduce(const IndexFilter &filter) {
207	  if (state_ != STATE_FEED) {
208	    LOG_ERROR("Feed streamers first");
209	    return IndexError_Uninitialized;
210	  }
211	  if (thread_pool_ == nullptr) {
212	    LOG_ERROR("Thread pool is not set");
213	    return IndexError_Uninitialized;
214	  }
215	
216	  ailego::ElapsedTime timer;
217	
218	  if (target_builder_ != nullptr) {
219	    if (is_sparse_) {
220	      LOG_ERROR("Builder-backed sparse merge is not supported");
221	      return IndexError_Unsupported;
222	    }
223	    int ret = this->reduce_with_builder(filter);
224	    if (ret != 0) {
225	      LOG_ERROR("Failed to build target index, ret=%d", ret);
226	      return ret;
227	    }
228	    stats_.set_reduced_costtime(timer.seconds());
229	    state_ = STATE_REDUCE;
230	    LOG_INFO("End provider-backed reduce. cost time: [%zu]s",
231	             (size_t)timer.seconds());
232	    return 0;
233	  }
234	
235	  std::vector<int> add_results(num_of_add_threads_, -1);
236	  auto add_group = thread_pool_->make_group();
237	
238	  std::vector<int> read_results(streamers_.size(), -1);
239	  // TODO: use id instead of key
240	  // When merging into a non-empty target (e.g. reusing one input as base),
241	  // append new docs after the existing ones instead of overwriting from 0.
242	  uint32_t id_offset = 0;
243	  uint32_t next_id = 0;
244	  if (target_builder_ == nullptr) {
245	    if (is_sparse_) {
246	      auto provider = target_streamer_->create_sparse_provider();
247	      if (provider) next_id = provider->count();
248	    } else {
249	      auto provider = target_streamer_->create_provider();
250	      if (provider) next_id = provider->count();
251	    }
252	  }
253	
254	  if (is_sparse_) {
255	    for (size_t i = 0; i < num_of_add_threads_; i++) {
256	      add_group->submit(ailego::Closure::New(
257	          this, &MixedStreamerReducer::add_sparse_vec, &add_results[i]));
258	    }
259	
260	    for (size_t i = 0; i < streamers_.size(); i++) {
261	      // due to filter, producing can't be parallel
262	      read_results[i] = read_sparse_vec(i, filter, id_offset, &next_id);
263	      id_offset += streamers_[i]->create_sparse_provider()->count();
264	    }
265	
266	    sparse_mt_list_.done();
267	  } else {
268	    for (size_t i = 0; i < num_of_add_threads_; i++) {
269	      add_group->submit(ailego::Closure::New(
270	          this, &MixedStreamerReducer::add_vec, &add_results[i]));
271	      // add_vec(&add_results[i]);
272	    }
273	
274	    for (size_t i = 0; i < streamers_.size(); i++) {
275	      auto provider = streamers_[i]->create_provider();
276	      if (!provider) {
277	        LOG_ERROR("Failed to create source provider, index=%zu", i);
278	        read_results[i] = IndexError_Runtime;
279	        break;
280	      }
281	      read_results[i] = read_vec(i, provider, filter, id_offset, &next_id);
282	      if (read_results[i] != 0) {
283	        break;
284	      }
285	      id_offset += provider->count();
286	    }
287	
288	    mt_list_.done();
289	  }
290	  add_group->wait_finish();
291	
292	  auto check_results = [](const std::vector<int> &results) -> bool {
293	    return std::all_of(std::begin(results), std::end(results),
294	                       [](int item) { return item == 0; });
295	  };
296	
297	  const auto read_error = std::find_if(read_results.begin(), read_results.end(),
298	                                       [](int item) { return item != 0; });
299	  if (read_error != read_results.end()) {
300	    LOG_ERROR("Get vector from entities failed");
301	    return *read_error;
302	  }
303	
304	  if (!check_results(add_results)) {
305	    LOG_ERROR("add vector failed");
306	    return IndexError_Runtime;
307	  }
308	
309	  stats_.set_reduced_costtime(timer.seconds());
310	  state_ = STATE_REDUCE;
311	
312	  LOG_INFO("End brute force reduce. cost time: [%zu]s",
313	           (size_t)timer.seconds());
314	  return 0;
315	}
316	
317	int MixedStreamerReducer::dump(const IndexDumper::Pointer &dumper) {
318	  LOG_INFO("Begin brute force reducer dump");
319	
320	  if (state_ != STATE_REDUCE) {
321	    LOG_WARN("Reduce first before dump");
322	    return IndexError_NoReady;
323	  }
324	
325	  ailego::ElapsedTime timer;
326	  int ret = 0;
327	  if (target_builder_ != nullptr) {
328	    ret = target_builder_->dump(dumper);
329	  } else {
330	    ret = target_streamer_->dump(dumper);
331	  }
332	  if (ret == 0 && merged_holder_ && merged_holder_->status() != 0) {
333	    ret = merged_holder_->status();
334	  }
335	  if (ret == IndexError_NotImplemented) {
336	    LOG_WARN("Dump index not implemented");
337	  } else if (ret < 0) {
338	    LOG_ERROR("Failed to dump in streamer");
339	  }
340	
341	  return ret;
342	}
343	
344	int MixedStreamerReducer::read_vec(size_t source_streamer_index,
345	                                   const IndexProvider::Pointer &provider,
346	                                   const IndexFilter &filter,
347	                                   const uint32_t id_offset,
348	                                   uint32_t *next_id) {
349	  const auto &streamer = streamers_[source_streamer_index];
350	  const auto &reformer = source_streamers_reformers_[source_streamer_index];
351	  const auto &quantizer = source_streamers_quantizers_[source_streamer_index];
352	  const IndexQueryMeta source_streamer_query_meta{streamer->meta().data_type(),
353	                                                  streamer->meta().dimension()};
354	
355	  bool need_revert = (target_streamer_->meta().reformer_name() !=
356	                          streamer->meta().reformer_name() &&
357	                      reformer != nullptr);
358	  if (target_builder_ && reformer) {
359	    need_revert = true;
360	  }
361	
362	  // Whether the bytes handed to add_vec are still in the original input
363	  // format and must be re-encoded (quantized/converted) by the target.
364	  // True for reverted legacy vectors, dequantized turbo vectors and plain
365	  // sources whose stored format already is the original one; false for raw
366	  // copies from a source whose stored layout matches the target.
367	  bool need_encode = need_revert || reformer == nullptr;
368	  if (quantizer != nullptr) {
369	    // Quantizer-encoded records can be copied raw only into an identical
370	    // target layout, including the metric: INT4 IP and L2 tails have the
371	    // same size but different meanings. Otherwise (or when a builder consumes
372	    // original vectors), dequantize back to the original format.
373	    const auto &source_meta = streamer->meta();
374	    const auto &target_meta = target_streamer_->meta();
375	    const bool same_layout =
376	        target_builder_ == nullptr &&
377	        turbo::QuantizerStorageDataTypeMatches(target_meta, source_meta) &&
378	        target_meta.quantizer_name() == source_meta.quantizer_name() &&
379	        target_meta.metric_name() == source_meta.metric_name() &&
380	        target_meta.data_type() == source_meta.data_type() &&
381	        target_meta.dimension() == source_meta.dimension() &&
382	        target_meta.unit_size() == source_meta.unit_size() &&
383	        target_meta.extra_meta_size() == source_meta.extra_meta_size();
384	    need_encode = !same_layout;
385	  }
386	
387	  if (!provider) {
388	    LOG_ERROR("Source provider is null, index=%zu", source_streamer_index);
389	    return IndexError_Runtime;
390	  }
391	  IndexProvider::Iterator::Pointer iterator = provider->create_iterator();
392	  if (!iterator) {
393	    LOG_ERROR("Failed to create source provider iterator, index=%zu",
394	              source_streamer_index);
395	    return IndexError_Runtime;
396	  }
397	
398	  while (iterator->is_valid()) {
399	    if (iterator->status() != 0) {
400	      return iterator->status();
401	    }
402	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
403	      LOG_DEBUG("read_vec cancelled.");
404	      return 0;
405	    }
406	    const uint64_t key = iterator->key();
407	    if (iterator->status() != 0) {
408	      return iterator->status();
409	    }
410	    if (filter(key + (uint64_t)id_offset)) {
411	      (*stats_.mutable_filtered_count())++;
412	      iterator->next();
413	      continue;
414	    }
415	
416	    const void *vector_data = iterator->data();
417	    if (iterator->status() != 0) {
418	      return iterator->status();
419	    }
420	    if (!vector_data) {
421	      LOG_ERROR("Failed to read source vector, index=%zu key=%zu",
422	                source_streamer_index, static_cast<size_t>(iterator->key()));
423	      return IndexError_ReadData;
424	    }
425	
426	    std::vector<uint8_t> bytes;
427	    bool needs_convert = false;
428	    if (quantizer != nullptr && need_encode) {
429	      std::string original_vector;
430	      if (quantizer->dequantize(vector_data, source_streamer_query_meta,
431	                                &original_vector) != 0) {
432	        LOG_ERROR("Failed to dequantize the vector, index=%zu key=%zu",
433	                  source_streamer_index, static_cast<size_t>(iterator->key()));
434	        return IndexError_Runtime;
435	      }
436	      bytes.resize(original_vector.size());
437	      memcpy(bytes.data(), original_vector.data(), bytes.size());
438	      needs_convert = true;
439	    } else if (need_revert) {
440	      std::string new_vector;
441	      if (reformer->revert(vector_data, source_streamer_query_meta,
442	                           &new_vector) != 0) {
443	        LOG_ERROR("Failed to revert the vector");
444	        return IndexError_Runtime;
445	      }
446	      bytes.resize(new_vector.size());
447	      memcpy(bytes.data(), new_vector.data(), bytes.size());
448	      needs_convert = true;
449	    } else {
450	      // TODO: eliminate the copy
451	      bytes.resize(provider->element_size());
452	      memcpy(bytes.data(), vector_data, bytes.size());
453	      needs_convert = need_encode;
454	    }
455	
456	    if (target_builder_ &&
457	        (bytes.size() != original_query_meta_.element_size() ||
458	         (!need_revert &&
459	          (provider->data_type() != original_query_meta_.data_type() ||
460	           provider->dimension() != original_query_meta_.dimension())))) {
461	      LOG_ERROR("Decoded source vector does not match the builder input");
462	      return IndexError_Mismatch;
463	    }
464	
465	    // TODO: use id instead of key
466	    if (!mt_list_.produce(
467	            VectorItem((*next_id)++, std::move(bytes), needs_convert))) {
468	      LOG_ERROR("Produce vector to queue failed. key[%lu]",
469	                (size_t)iterator->key());
470	      return IndexError_Runtime;
471	    }
472	    iterator->next();
473	  }
474	  return iterator->status();
475	}
476	
477	void MixedStreamerReducer::add_vec(int *result) {
478	  ailego::ElapsedTime timer;
479	  auto target_streamer_context = target_streamer_->create_context();
480	  auto target_streamer_query_meta = IndexQueryMeta{
481	      IndexMeta::MetaType::MT_DENSE, target_streamer_->meta().data_type(),
482	      target_streamer_->meta().dimension()};
483	  // Quantizer-encoded layouts append an extra meta tail per record
484	  // (e.g. turbo Int8Quantizer); without it the element size would not match
485	  // the streamer meta and every add would be rejected.
486	  target_streamer_query_meta.set_extra_meta_size(
487	      target_streamer_->meta().extra_meta_size());
488	
489	  AILEGO_DEFER([&]() {
490	    // make producer quit
491	    mt_list_.done();
492	  });
493	
494	  VectorItem vector_item;
495	  while (mt_list_.consume(&vector_item)) {
496	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
497	      LOG_DEBUG("add_vec cancelled.");
498	      return;
499	    }
500	
501	    const void *vector = vector_item.vec_.data();
502	    std::string new_vector;
503	    IndexQueryMeta add_meta = target_streamer_query_meta;
504	
505	    if (vector_item.needs_convert_) {
506	      // Bytes are still in the original input format; re-encode them into
507	      // the target layout. A target without quantizer or reformer stores
508	      // the original format directly, so no encoding is needed.
509	      if (target_streamer_quantizer_ != nullptr) {
510	        IndexQueryMeta quantized_meta;
511	        if (target_streamer_quantizer_->quantize(vector, original_query_meta_,
512	                                                 &new_vector,
513	                                                 &quantized_meta) != 0) {
514	          LOG_ERROR("Failed to quantize vector. pkey[%zu]",
515	                    (size_t)vector_item.pkey_);
516	          *result = IndexError_Runtime;
517	          return;
518	        }
519	        vector = new_vector.data();
520	        add_meta = quantized_meta;
521	      } else if (target_streamer_reformer_ != nullptr) {
522	        IndexQueryMeta new_meta;
523	        if (target_streamer_reformer_->convert(vector, original_query_meta_,
524	                                               &new_vector, &new_meta) != 0) {
525	          LOG_ERROR("Failed to transform vector");
526	          *result = IndexError_Runtime;
527	          return;
528	        }
529	        vector = new_vector.data();
530	      }
531	    }
532	
533	    // TODO: use id instead of key
534	    int ret = target_streamer_->add_with_id_impl(
535	        (uint32_t)vector_item.pkey_, vector, add_meta, target_streamer_context);
536	    if (ret != 0) {
537	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
538	                ret, IndexError::What(ret), (size_t)vector_item.pkey_);
539	      *result = ret;
540	      return;
541	    }
542	  }
543	
544	  *result = 0;
545	  LOG_DEBUG("add_vec. cost time: [%zu]s", (size_t)timer.seconds());
546	  return;
547	}
548	
549	void MixedStreamerReducer::add_sparse_vec(int *result) {
550	  ailego::ElapsedTime timer;
551	  auto target_streamer_context = target_streamer_->create_context();
552	  auto target_streamer_query_meta = IndexQueryMeta{
553	      IndexMeta::MetaType::MT_SPARSE,
554	      target_streamer_->meta().data_type(),
555	  };
556	
557	  auto need_convert = !is_target_and_source_same_reformer_ &&
558	                      target_streamer_reformer_ != nullptr;
559	
560	  AILEGO_DEFER([&]() {
561	    // make producer quit
562	    sparse_mt_list_.done();
563	  });
564	
565	  SparseVectorItem sparse_vector_item;
566	  while (sparse_mt_list_.consume(&sparse_vector_item)) {
567	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
568	      LOG_DEBUG("add_sparse_vec cancelled.");
569	      return;
570	    }
571	    auto sparse_count = sparse_vector_item.sparse_indices_.size();
572	    auto indices = sparse_vector_item.sparse_indices_.data();
573	    auto values = sparse_vector_item.sparse_values_.data();
574	
575	    std::string converted_sparse_values_buffer;
576	    if (need_convert) {
577	      IndexQueryMeta new_meta;
578	      if (target_streamer_reformer_->convert(
579	              sparse_count, indices, values, original_query_meta_,
580	              &converted_sparse_values_buffer, &new_meta) != 0) {
581	        LOG_ERROR("Failed to transform vector");
582	        *result = IndexError_Runtime;
583	        return;
584	      }
585	      values = converted_sparse_values_buffer.data();
586	      target_streamer_query_meta = new_meta;
587	    }
588	
589	    // TODO: use id instead of key
590	    int ret = target_streamer_->add_with_id_impl(
591	        (uint32_t)sparse_vector_item.pkey_, sparse_count, indices, values,
592	        target_streamer_query_meta, target_streamer_context);
593	    if (ret != 0) {
594	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
595	                ret, IndexError::What(ret), (size_t)sparse_vector_item.pkey_);
596	      *result = ret;
597	      return;
598	    }
599	  }
600	
601	  *result = 0;
602	  LOG_DEBUG("add_sparse_vec. cost time: [%zu]s", (size_t)timer.seconds());
603	  return;
604	}
605	
606	
607	int MixedStreamerReducer::read_sparse_vec(size_t source_streamer_index,
608	                                          const IndexFilter &filter,
609	                                          const uint32_t id_offset,
610	                                          uint32_t *next_id) {
611	  const auto &streamer = streamers_[source_streamer_index];
612	  const auto &reformer = source_streamers_reformers_[source_streamer_index];
613	  const bool need_revert =
614	      !is_target_and_source_same_reformer_ && reformer != nullptr;
615	
616	  IndexStreamer::SparseProvider::Pointer provider =
617	      streamer->create_sparse_provider();
618	  IndexStreamer::SparseProvider::Iterator::Pointer iterator =
619	      provider->create_iterator();
620	
621	  while (iterator->is_valid()) {
622	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
623	      LOG_DEBUG("read_sparse_vec cancelled.");
624	      return 0;
625	    }
626	    if (filter(iterator->key() + (uint64_t)id_offset)) {
627	      (*stats_.mutable_filtered_count())++;
628	      iterator->next();
629	      continue;
630	    }
631	
632	    auto sparse_count = iterator->sparse_count();
633	    std::vector<uint32_t> sparse_indices(sparse_count);
634	    std::string sparse_values;
635	
636	    if (need_revert) {
637	      std::string new_sparse_values;
638	      if (reformer->revert(iterator->sparse_count(), iterator->sparse_indices(),
639	                           iterator->sparse_data(),
640	                           {
641	                               IndexMeta::MetaType::MT_SPARSE,
642	                               streamer->meta().data_type(),
643	                           },
644	                           &new_sparse_values) != 0) {
645	        LOG_ERROR("Failed to revert the sparse vector");
646	        return IndexError_Runtime;
647	      }
648	      sparse_values = std::move(new_sparse_values);
649	    } else {
650	      sparse_values.resize(sparse_count * streamer->meta().unit_size());
651	      memcpy(sparse_values.data(), iterator->sparse_data(),
652	             sparse_values.size());
653	    }
654	
655	    // TODO: eliminate the copy
656	    memcpy(sparse_indices.data(), iterator->sparse_indices(),
657	           sparse_indices.size() * sizeof(uint32_t));
658	
659	    // TODO: use id instead of key
660	    if (!sparse_mt_list_.produce(SparseVectorItem((*next_id)++,
661	                                                  std::move(sparse_indices),
662	                                                  std::move(sparse_values)))) {
663	      LOG_ERROR("Produce vector to queue failed. key[%lu]",
664	                (size_t)iterator->key());
665	      return IndexError_Runtime;
666	    }
667	    iterator->next();
668	  }
669	  return 0;
670	}
671	
672	int MixedStreamerReducer::reduce_with_builder(const IndexFilter &filter) {
673	  std::vector<MergedProviderIndexHolder::Source> sources;
674	  sources.reserve(streamers_.size());
675	
676	  for (size_t i = 0; i < streamers_.size(); ++i) {
677	    MergedProviderIndexHolder::Source source;
678	    source.owner = streamers_[i];
679	    source.reformer = source_streamers_reformers_[i];
680	    source.quantizer = source_streamers_quantizers_[i];
681	    const auto &meta = streamers_[i]->meta();
682	    source.provider_meta = IndexQueryMeta{
683	        meta.meta_type(),
684	        meta.data_type(),
685	        meta.unit_size(),
686	        meta.dimension(),
687	        source.quantizer ? static_cast<uint32_t>(source.quantizer->type()) : 0,
688	        meta.extra_meta_size()};
689	    // Builders consume original vectors, not encoded records. Plain FP32
690	    // quantization is an identity transform; keep its zero-copy ordinal path.
691	    // Cosine normalization and FP16/INT8/INT4 storage must be decoded first.
692	    source.need_revert =
693	        source.quantizer
694	            ? source.quantizer->type() != turbo::QuantizeType::kFp32 ||
695	                  meta.extra_meta_size() != 0
696	            : source.reformer != nullptr;
697	    sources.emplace_back(std::move(source));
698	  }
699	
700	  auto holder = std::make_shared<MergedProviderIndexHolder>(
701	      original_query_meta_, std::move(sources));
702	  int ret = holder->init(filter, stop_flag_);
703	  if (ret != 0) {
704	    LOG_ERROR("Failed to initialize merged provider holder, ret=%d", ret);
705	    return ret;
706	  }
707	
708	  stats_.set_filtered_count(holder->filtered_count());
709	  merged_holder_ = holder;
710	
711	  AILEGO_DEFER([&]() { holder->set_stop_flag(nullptr); });
712	  IndexHolder::Pointer target_holder = holder;
713	  // IVF and DiskAnn propagate source read failures during dump.
714	  // Other builders retain an owned multipass snapshot, as before, so their
715	  // dump paths never depend on a source provider or its deferred error state.
716	  if (target_builder_->name() != "IVFBuilder" &&
717	      target_builder_->name() != "DiskAnnBuilder") {
718	    switch (holder->data_type()) {
719	      case IndexMeta::DataType::DT_FP32:
720	        ret = MaterializeMergedInput<IndexMeta::DataType::DT_FP32, float>(
721	            holder, &target_holder);
722	        break;
723	      case IndexMeta::DataType::DT_FP16:
724	        ret = MaterializeMergedInput<IndexMeta::DataType::DT_FP16,
725	                                     ailego::Float16>(holder, &target_holder);
726	        break;
727	      case IndexMeta::DataType::DT_INT8:
728	        ret = MaterializeMergedInput<IndexMeta::DataType::DT_INT8, int8_t>(
729	            holder, &target_holder);
730	        break;
731	      default:
732	        ret = IndexError_Unsupported;
733	        break;
734	    }
735	    if (ret != 0) {
736	      return ret;
737	    }
738	  }
739	  return this->index_build(std::move(target_holder));
740	}
741	
742	int MixedStreamerReducer::index_build(IndexHolder::Pointer target_holder) {
743	  auto threads =
744	      std::make_shared<BorrowedSingleQueueIndexThreads>(*thread_pool_);
745	  if (target_builder_converter_) {
746	    int ret = core::IndexConverter::TrainAndTransform(target_builder_converter_,
747	                                                      target_holder, threads);
748	    if (ret != 0) {
749	      LOG_ERROR("Failed to convert target holder, ret=%d", ret);
750	      return merged_holder_ && merged_holder_->status() != 0
751	                 ? merged_holder_->status()
752	                 : ret;
753	    }
754	    target_holder = target_builder_converter_->result();
755	    if (!target_holder) {
756	      LOG_ERROR("Target builder converter returned a null holder");
757	      return core::IndexError_Runtime;
758	    }
759	  }
760	  int ret = target_builder_->train(threads, target_holder);
761	  if (merged_holder_ && merged_holder_->status() != 0) {
762	    return merged_holder_->status();
763	  }
764	  if (ret != 0) {
765	    LOG_ERROR("Failed to train target builder, ret=%d", ret);
766	    return ret;
767	  }
768	  ret = target_builder_->build(std::move(threads), target_holder);
769	  if (merged_holder_ && merged_holder_->status() != 0) {
770	    return merged_holder_->status();
771	  }
772	  if (ret != 0) {
773	    LOG_ERROR("Failed to build target index, ret=%d", ret);
774	    return ret;
775	  }
776	  return 0;
777	}
